import React, {useEffect, useState} from 'react'
import {X} from 'lucide-react'
import {supabase} from './supabase'

const products=['Yuca','Ñampí','Cabeza de ñampí','Camote','Caña de azúcar','Jengibre','Cúrcuma','Malanga lila','Malanga blanca','Malanga taro','Papa china','Ñame','Chayote','Ayote']
const initial=()=>({fecha:new Date().toLocaleDateString('en-CA'),fecha_labor:'',campo_promedio_caja_kg:'',campo_tara_caja_kg:0,campo_tierra_caja_kg:0,campo_muestra_cajas:[],campo_sacos:0,campo_promedio_saco_kg:0,campo_descuento_rechazo_pct:10,campo_precio_rechazo:0,campo_muestra_sacos:[],campo_encargados:0,campo_otros_costos:0,campo_otros_detalle:'',planilla_proveedor_id:'',boleta_campo_referencia:'',boleta_entrada_id:'',proveedor_id:'',productor_nombre:'',productor_direccion:'',productor_telefono:'',productor_cedula:'',finca_lote_id:'',producto:'',cantidad_comprada:'',cantidad_recibida:'',unidad:'Quintales (46 kg)',tipo_compra:'A rendimiento',peso_caja_camion_kg:'',precio_puesto_camion:'',flete_proveedor_id:'',precio_europa:'',precio_eeuu:'',precio_segunda_gruesa:'',precio_segunda_menuda:'',precio_rechazo:'',precio_campo:'',precio_en_pie:'',precio_nampi_rendimiento:'',precio_cabeza_rendimiento:'',flete:'',cuadrilla_arranca:'',adelanto:'',rebaja_planilla_flete:'',tipo_cambio_resultado:'',chofer:'',transportista:'',placa:'',observaciones:''})

export default function PurchaseOrderModal({order,close,onSaved,onOpenReceipt,userId}){
  const [form,setForm]=useState(()=>order?{...Object.fromEntries(Object.entries(initial()).map(([key,value])=>[key,order[key]??value])),...(order.tipo_compra==='En campo'&&order.unidad!=='Cajas'?{cantidad_comprada:'',unidad:'Cajas'}:{})}:initial());const [providers,setProviders]=useState([]);const [receipts,setReceipts]=useState([]);const [linkedReceipts,setLinkedReceipts]=useState([])
  const [newProducer,setNewProducer]=useState(null)
  const [newCarrier,setNewCarrier]=useState('')
  const [newCrew,setNewCrew]=useState('')
  const [yieldDetails,setYieldDetails]=useState([])
  const [directSales,setDirectSales]=useState([])
  const [pieSale,setPieSale]=useState(()=>({boleta_id:'',fecha:new Date().toLocaleDateString('en-CA'),producto:'Cabeza de ñampí',comprador:'',cantidad:'',unidad:'Sacos',peso_saco_kg:'',precio_unitario:'',moneda:'CRC'}))
  const [addingPieSale,setAddingPieSale]=useState(false)
  const [openingReceipt,setOpeningReceipt]=useState(false)
  const [saleLines,setSaleLines]=useState({})
  const [farms,setFarms]=useState([]),[lots,setLots]=useState([])
  const [newFarm,setNewFarm]=useState(''),[newLot,setNewLot]=useState(''),[farmId,setFarmId]=useState(''),[lotYear,setLotYear]=useState(new Date().getFullYear())
  const [saving,setSaving]=useState(false);const [error,setError]=useState('')
  const ready=form.tipo_compra==='Producto listo/parafinado'
  const truck=form.tipo_compra==='Puesto en camión'
  const field=form.tipo_compra==='En campo'&&form.producto==='Yuca'
  const yucaRendimiento=form.tipo_compra==='A rendimiento'&&form.producto==='Yuca'
  const nampi=['Ñampí','Cabeza de ñampí'].includes(form.producto)&&!ready
  const nampiEnPie=nampi&&form.tipo_compra==='En pie'
  const ownProducer=providers.find(p=>p.id===form.proveedor_id)?.tipo==='Propio'
  const chosenLot=lots.find(l=>l.id===form.finca_lote_id)
  const selectedFarmId=chosenLot?.finca_id||farmId
  const truckQuintals=Number(form.cantidad_comprada||0)*Number(form.peso_caja_camion_kg||0)/46
  const truckAmount=truckQuintals*Number(form.precio_puesto_camion||0)
  const [boxSample,setBoxSample]=useState(()=>Array.from({length:20},(_,i)=>String(order?.campo_muestra_cajas?.[i]??'')))
  const [sackSample,setSackSample]=useState(()=>Array.from({length:20},(_,i)=>String(order?.campo_muestra_sacos?.[i]??'')))
  const sampleWeights=slots=>slots.filter(value=>value!=='').map(Number)
  const boxWeights=sampleWeights(boxSample),sackWeights=sampleWeights(sackSample)
  const sampleAverage=weights=>String(Math.round(weights.reduce((sum,weight)=>sum+weight,0)/weights.length*1000)/1000)
  const changeSample=(slots,setSlots,index,value,averageKey)=>{
    const next=[...slots];next[index]=value;setSlots(next)
    const weights=sampleWeights(next)
    if(weights.length&&weights.every(weight=>Number.isFinite(weight)&&weight>0))change(averageKey,sampleAverage(weights))
  }
  const weightFields=(slots,setSlots,averageKey,unit)=><div className="weight-sample wide"><b>Muestra de {unit} (hasta 20 pesos, kg, opcional)</b><div className="weight-sample-grid">{slots.map((value,index)=><label key={index}>{index+1}<input type="number" min="0.001" step="0.001" inputMode="decimal" aria-label={`Peso ${index+1} de ${unit}`} value={value} onChange={e=>changeSample(slots,setSlots,index,e.target.value,averageKey)}/></label>)}</div><small>{sampleWeights(slots).length} de 20 pesos anotados</small></div>
  const fieldFirstKg=Number(form.cantidad_comprada||0)*Math.max(0,Number(form.campo_promedio_caja_kg||0)-Number(form.campo_tara_caja_kg||0)-Number(form.campo_tierra_caja_kg||0))
  const fieldRejectKg=Number(form.campo_sacos||0)*Number(form.campo_promedio_saco_kg||0)*(1-Number(form.campo_descuento_rechazo_pct||0)/100)
  const fieldFirstPay=fieldFirstKg/46*Number(form.precio_campo||0),fieldRejectPay=fieldRejectKg/46*Number(form.campo_precio_rechazo||0)
  const outsideSales=directSales.reduce((totals,v)=>{totals[v.moneda]=(totals[v.moneda]||0)+Number(v.cantidad)*Number(v.precio_unitario);return totals},{CRC:0,USD:0})
  const pieYieldKg=product=>yieldDetails.filter(r=>r.producto===product).reduce((sum,r)=>sum+Number(r.kg_resultado||0),0)
  const outsideKg=product=>directSales.filter(v=>v.producto===product).reduce((sum,v)=>sum+Number(v.cantidad)*(v.unidad==='Sacos'?Number(v.peso_saco_kg):46),0)
  const pieHypothetical=['Ñampí','Cabeza de ñampí'].reduce((sum,product)=>sum+(pieYieldKg(product)+outsideKg(product))/46*Number(form[product==='Ñampí'?'precio_nampi_rendimiento':'precio_cabeza_rendimiento']||0),0)
  const pieMissingPrice=['Ñampí','Cabeza de ñampí'].some(product=>pieYieldKg(product)+outsideKg(product)>0&&form[product==='Ñampí'?'precio_nampi_rendimiento':'precio_cabeza_rendimiento']==='')
  const pieRealCost=Number(form.precio_en_pie||0)+Number(form.cuadrilla_arranca||0)+Number(form.flete||0)
  const fieldCrewCost=Number(form.cuadrilla_arranca||0)+Number(form.campo_encargados||0)+Number(form.campo_otros_costos||0)
  const fieldTotalCost=fieldFirstPay+fieldRejectPay+fieldCrewCost+Number(form.flete||0)
  useEffect(()=>{let active=true;supabase.from('proveedores').select('id,nombre,telefono,residencia,cedula,zona,tipo,productos').eq('activo',true).order('nombre').then(({data,error:loadError})=>{if(!active)return;if(loadError)setError('No se pudieron cargar los productores registrados.');else setProviders(data||[])});return()=>{active=false}},[])
  useEffect(()=>{let active=true;Promise.all([supabase.from('fincas').select('id,nombre').eq('activa',true).order('nombre'),supabase.from('lotes_finca').select('id,finca_id,anio,nombre,producto').order('anio',{ascending:false})]).then(([a,b])=>{if(!active)return;if(a.error||b.error)setError('No se pudieron cargar las fincas y lotes.');else{setFarms(a.data||[]);setLots(b.data||[])}});return()=>{active=false}},[])
  useEffect(()=>{let active=true;supabase.from('boletas_entrada').select('id,codigo,producto,fecha_hora,orden_compra_id').order('fecha_hora',{ascending:false}).limit(100).then(({data})=>{if(!active)return;setReceipts((data||[]).filter(item=>!item.orden_compra_id));setLinkedReceipts((data||[]).filter(item=>item.orden_compra_id===order?.id))});return()=>{active=false}},[order?.id])
  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('boletas_entrada').select('codigo,boleta_rendimientos(producto,calidad,kg_resultado,paga_productor,cajas,presentacion_kg,kg_manual,orden_venta_linea_id)').eq('orden_compra_id',order.id).then(({data})=>{if(active)setYieldDetails((data||[]).flatMap(b=>(b.boleta_rendimientos||[]).map(r=>({...r,boleta:b.codigo}))))});return()=>{active=false}},[order?.id])
  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('boletas_entrada').select('id,codigo,fecha_hora').eq('orden_compra_id',order.id).order('fecha_hora').then(({data})=>{if(active)setLinkedReceipts(data||[])});return()=>{active=false}},[order?.id])
  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('ventas_externas_en_pie').select('*').eq('orden_compra_id',order.id).order('fecha').then(({data})=>{if(active)setDirectSales(data||[])});return()=>{active=false}},[order?.id])
  useEffect(()=>{const ids=[...new Set(yieldDetails.map(r=>r.orden_venta_linea_id).filter(Boolean))];if(!ids.length){setSaleLines({});return}let active=true;supabase.from('ordenes_venta_lineas').select('id,precio_caja,precio_quintal,ordenes_venta(moneda,finalizada_en)').in('id',ids).then(({data,error:loadError})=>{if(active&&!loadError)setSaleLines(Object.fromEntries((data||[]).map(line=>[line.id,line])))});return()=>{active=false}},[yieldDetails])
  const yieldPrice=quality=>nampi?'precio_campo':quality==='Exportable Europa'?'precio_europa':quality==='Exportable estadounidense'?'precio_eeuu':quality==='Segunda gruesa'?'precio_segunda_gruesa':quality==='Segunda menuda'?'precio_segunda_menuda':quality.startsWith('Rechazo')?'precio_rechazo':null
  const yieldKg=r=>Number(r.cajas)>0?Number(r.cajas)*Number(r.presentacion_kg||0):Number(r.kg_resultado||0)
  const yieldAmount=r=>{if(nampiEnPie)return 0;const key=yieldPrice(r.calidad);if(truck)return !key?0:form[key]!==''?yieldKg(r)/46*Number(form[key]):null;return !r.paga_productor?0:key&&form[key]!==''?yieldKg(r)/46*Number(form[key]):null}
  const pendingPrice=yieldDetails.some(r=>(truck||r.paga_productor)&&yieldAmount(r)===null)
  const yieldTotal=yieldDetails.reduce((sum,r)=>sum+(yieldAmount(r)||0),0)
  const sold=yieldDetails.reduce((totals,r)=>{const line=saleLines[r.orden_venta_linea_id],sale=line?.ordenes_venta;if(!sale?.finalizada_en)return totals;const currency=sale.moneda||'USD',amount=line.precio_quintal!=null?yieldKg(r)/46*Number(line.precio_quintal):Number(r.cajas||0)*Number(line.precio_caja||0);totals[currency]=(totals[currency]||0)+amount;return totals},{CRC:0,USD:0})
  const pieRevenue=sold.CRC+outsideSales.CRC+(sold.USD+outsideSales.USD)*Number(form.tipo_cambio_resultado||0)
  const change=(name,value)=>setForm(current=>({...current,[name]:value}))
  const chooseProvider=value=>{const provider=providers.find(item=>item.id===value);setForm(current=>({...current,proveedor_id:value,productor_nombre:provider?.nombre||'',productor_direccion:provider?.residencia||'',productor_telefono:provider?.telefono||'',productor_cedula:provider?.cedula||'',finca_lote_id:provider?.tipo==='Propio'?current.finca_lote_id:''}))}
  const createCarrier=async()=>{if(!newCarrier.trim()){setError('Escriba el nombre de quien hace el flete.');return}setSaving(true);setError('');const {data,error:e}=await supabase.from('proveedores').insert({nombre:newCarrier.trim(),tipo:'Transportista'}).select('id,nombre,tipo').single();setSaving(false);if(e){setError(`No se pudo guardar el transportista: ${e.message}`);return}setProviders(current=>[...current,data].sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')));setForm(current=>({...current,flete_proveedor_id:data.id,transportista:data.nombre}));setNewCarrier('')}
  const createCrew=async()=>{if(!newCrew.trim()){setError('Escriba el nombre de quien cobra la planilla.');return}setSaving(true);setError('');const {data,error:e}=await supabase.from('proveedores').insert({nombre:newCrew.trim(),tipo:'Cuadrilla'}).select('id,nombre,tipo').single();setSaving(false);if(e){setError(`No se pudo guardar la cuadrilla: ${e.message}`);return}setProviders(current=>[...current,data].sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')));change('planilla_proveedor_id',data.id);setNewCrew('')}
  const savePieSale=async()=>{
    const qty=Number(pieSale.cantidad),price=Number(pieSale.precio_unitario)
    if(!order?.id||!pieSale.boleta_id||!linkedReceipts.some(b=>b.id===pieSale.boleta_id)||!pieSale.fecha||!pieSale.comprador.trim()||!Number.isFinite(qty)||qty<=0||pieSale.precio_unitario===''||!Number.isFinite(price)||price<0||pieSale.unidad==='Sacos'&&(!Number.isInteger(qty)||!(Number(pieSale.peso_saco_kg)>0))){setError('Complete boleta, comprador, cantidad, peso por saco si corresponde y precio.');return}
    setAddingPieSale(true);setError('')
    const {data,error:e}=await supabase.from('ventas_externas_en_pie').insert({orden_compra_id:order.id,boleta_id:pieSale.boleta_id,fecha:pieSale.fecha,producto:pieSale.producto,comprador:pieSale.comprador.trim(),cantidad:qty,unidad:pieSale.unidad,peso_saco_kg:pieSale.unidad==='Sacos'?Number(pieSale.peso_saco_kg):null,precio_unitario:price,moneda:pieSale.moneda}).select('*').single()
    setAddingPieSale(false)
    if(e){setError(`No se pudo guardar la venta directa: ${e.message}`);return}
    setDirectSales(current=>[...current,data]);setPieSale(current=>({...current,comprador:'',cantidad:'',peso_saco_kg:'',precio_unitario:''}))
  }
  const openPlantReceipt=async id=>{setOpeningReceipt(true);setError('');try{await onOpenReceipt(id)}catch(e){setError(`No se pudo abrir la boleta de planta: ${e.message}`);setOpeningReceipt(false)}}
  const createFarm=async()=>{if(!newFarm.trim()){setError('Escriba el nombre de la finca.');return}setSaving(true);const {data,error:e}=await supabase.from('fincas').insert({nombre:newFarm.trim()}).select('id,nombre').single();setSaving(false);if(e){setError(`No se pudo crear la finca: ${e.message}`);return}setFarms(current=>[...current,data].sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')));setFarmId(data.id);setForm(current=>({...current,finca_lote_id:''}));setNewFarm('');setError('')}
  const createLot=async()=>{if(!selectedFarmId||!newLot.trim()||!Number.isInteger(Number(lotYear))||Number(lotYear)<2000||Number(lotYear)>2100){setError('Indique finca, año y nombre del lote.');return}setSaving(true);const {data,error:e}=await supabase.from('lotes_finca').insert({finca_id:selectedFarmId,anio:Number(lotYear),nombre:newLot.trim(),producto:form.producto||null}).select('id,finca_id,anio,nombre,producto').single();setSaving(false);if(e){setError(`No se pudo crear el lote: ${e.message}`);return}setLots(current=>[data,...current]);setForm(current=>({...current,finca_lote_id:data.id}));setNewLot('');setError('')}
  const createProducer=async()=>{
    if(!newProducer.nombre.trim()){setError('Escriba el nombre del productor.');return}
    setSaving(true);setError('')
    const {data,error:producerError}=await supabase.from('proveedores').insert({nombre:newProducer.nombre.trim(),cedula:newProducer.cedula.trim()||null,telefono:newProducer.telefono.trim()||null,residencia:newProducer.residencia.trim()||null,zona:newProducer.zona.trim()||null,tipo:newProducer.tipo,productos:newProducer.productos.trim()?newProducer.productos.split(',').map(x=>x.trim()).filter(Boolean):[]}).select('id,nombre,telefono,residencia,cedula,zona,tipo,productos').single()
    setSaving(false);if(producerError){setError(`No se pudo guardar el productor: ${producerError.message}`);return}
    setProviders(current=>[...current,data].sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')));setNewProducer(null);chooseProviderFrom(data)
  }
  const chooseProviderFrom=provider=>setForm(current=>({...current,proveedor_id:provider.id,productor_nombre:provider.nombre,productor_direccion:provider.residencia||'',productor_telefono:provider.telefono||'',productor_cedula:provider.cedula||''}))
  const save=async()=>{
    if(!form.fecha){setError('Indique la fecha de la orden.');return}
    if(!form.proveedor_id&&!order?.productor_nombre){setError('Seleccione el productor o guarde la ficha del productor nuevo.');return}
    if(!form.producto){setError('Seleccione el producto.');return}
    if(ownProducer&&!chosenLot){setError('Para producto propio seleccione la finca y el lote del año; puede crearlos aquí mismo.');return}
    if(field){
      const required=Number(form.cantidad_comprada)>0&&Number.isInteger(Number(form.cantidad_comprada))&&Number(form.campo_promedio_caja_kg)>Number(form.campo_tara_caja_kg)+Number(form.campo_tierra_caja_kg)&&Number(form.precio_campo)>0
      const rejects=Number.isInteger(Number(form.campo_sacos))&&Number(form.campo_sacos)>=0&&(Number(form.campo_sacos)===0||Number(form.campo_promedio_saco_kg)>0&&Number(form.campo_precio_rechazo)>0)
      const percentage=Number(form.campo_descuento_rechazo_pct)>=0&&Number(form.campo_descuento_rechazo_pct)<100
      const samples=[boxWeights,sackWeights].every(a=>a.length<=20&&a.every(w=>Number.isFinite(w)&&w>0))
      const deductions=[form.campo_tara_caja_kg,form.campo_tierra_caja_kg,form.cuadrilla_arranca,form.flete,form.campo_encargados,form.campo_otros_costos].every(v=>Number.isFinite(Number(v))&&Number(v)>=0)
      if(!required||!rejects||!percentage||!samples||!deductions){setError('Revise cajas enteras, pesos netos, precios, rechazo y descuentos. Cada muestra admite hasta 20 pesos positivos.');return}
    }
    if(truck&&(!Number.isInteger(Number(form.cantidad_comprada))||!(Number(form.cantidad_comprada)>0)||!(Number(form.peso_caja_camion_kg)>0)||!(Number(form.precio_puesto_camion)>0))){setError('Indique cajas enteras, kilos por caja y precio por quintal de 46 kg de la compra puesta en camión.');return}
    if((field&&fieldCrewCost>0||nampiEnPie&&Number(form.cuadrilla_arranca)>0)&&!form.planilla_proveedor_id){setError('Seleccione a quién se le paga la planilla, encargados y otros costos de campo.');return}
    if(Number(form.flete)>0&&!form.flete_proveedor_id){setError('Seleccione a quién se le paga el flete o registre un transportista nuevo.');return}
    const bought=form.cantidad_comprada===''?null:Number(form.cantidad_comprada)
    const arrived=form.cantidad_recibida===''?null:Number(form.cantidad_recibida)
    if((bought!==null&&(!Number.isFinite(bought)||bought<0))||(arrived!==null&&(!Number.isFinite(arrived)||arrived<0))){setError('Las cantidades deben ser números iguales o mayores que cero.');return}
    const moneyFields=['precio_europa','precio_eeuu','precio_segunda_gruesa','precio_segunda_menuda','precio_rechazo','precio_campo','precio_en_pie','flete','cuadrilla_arranca','adelanto']
    if(moneyFields.some(key=>form[key]!==''&&(!Number.isFinite(Number(form[key]))||Number(form[key])<0))){setError('Los precios y adelantos deben ser números iguales o mayores que cero.');return}
    if(ready&&!(Number(form.precio_europa)>0)){setError('Indique el precio de la yuca Europa lista por quintal de 46 kg. Las otras calidades pueden quedar vacías.');return}
    if(nampi&&!nampiEnPie&&!truck&&!(Number(form.precio_campo)>0)){setError(`Indique el precio del ${form.producto.toLowerCase()} puesto en planta por quintal de 46 kg.`);return}
    if(nampiEnPie&&!(Number(form.precio_en_pie)>0)){setError(`Indique el precio acordado por el lote de ${form.producto.toLowerCase()} en pie.`);return}
    if(nampiEnPie&&['precio_nampi_rendimiento','precio_cabeza_rendimiento'].some(k=>form[k]!==''&&(!Number.isFinite(Number(form[k]))||Number(form[k])<0))){setError('Revise los precios de referencia a rendimiento.');return}
    if(form.rebaja_planilla_flete!==''&&(!Number.isFinite(Number(form.rebaja_planilla_flete))||Number(form.rebaja_planilla_flete)<0)){setError('La rebaja de planilla y flete debe ser un monto igual o mayor que cero.');return}
    if(form.tipo_cambio_resultado!==''&&(!Number.isFinite(Number(form.tipo_cambio_resultado))||Number(form.tipo_cambio_resultado)<=0)){setError('El tipo de cambio para el resultado debe ser mayor que cero.');return}
    setSaving(true);setError('')
    const prices=Object.fromEntries(moneyFields.map(key=>[key,(ready&&['precio_eeuu','precio_segunda_gruesa','precio_segunda_menuda','precio_rechazo','precio_campo','precio_en_pie'].includes(key))||(nampi&&['precio_europa','precio_eeuu','precio_segunda_gruesa','precio_segunda_menuda','precio_rechazo',nampiEnPie?'precio_campo':'precio_en_pie'].includes(key))?null:form[key]===''?null:Number(form[key])]))
    const payload={...(field?{campo_promedio_caja_kg:Number(form.campo_promedio_caja_kg),campo_tara_caja_kg:Number(form.campo_tara_caja_kg),campo_tierra_caja_kg:Number(form.campo_tierra_caja_kg),campo_muestra_cajas:boxWeights,campo_sacos:Number(form.campo_sacos),campo_promedio_saco_kg:Number(form.campo_promedio_saco_kg),campo_descuento_rechazo_pct:Number(form.campo_descuento_rechazo_pct),campo_precio_rechazo:Number(form.campo_precio_rechazo),campo_muestra_sacos:sackWeights,campo_encargados:Number(form.campo_encargados),campo_otros_costos:Number(form.campo_otros_costos),campo_otros_detalle:form.campo_otros_detalle.trim()||null,planilla_proveedor_id:fieldCrewCost>0?form.planilla_proveedor_id:null}:{}),...((nampiEnPie)?{planilla_proveedor_id:Number(form.cuadrilla_arranca)>0?form.planilla_proveedor_id:null,precio_nampi_rendimiento:form.precio_nampi_rendimiento===''?null:Number(form.precio_nampi_rendimiento),precio_cabeza_rendimiento:form.precio_cabeza_rendimiento===''?null:Number(form.precio_cabeza_rendimiento)}:{}),fecha:form.fecha,fecha_labor:form.fecha_labor||null,boleta_campo_referencia:form.boleta_campo_referencia.trim()||null,proveedor_id:form.proveedor_id||null,productor_nombre:form.productor_nombre.trim(),productor_direccion:form.productor_direccion.trim()||null,productor_telefono:form.productor_telefono.trim()||null,productor_cedula:form.productor_cedula.trim()||null,finca_lote_id:ownProducer?chosenLot.id:null,lugar:ownProducer?farms.find(f=>f.id===chosenLot.finca_id)?.nombre||null:order?.lugar||null,producto:form.producto,cantidad_comprada:bought,cantidad_recibida:truck?bought:arrived,unidad:truck||field?'Cajas':form.unidad,tipo_compra:form.tipo_compra,peso_caja_camion_kg:truck?Number(form.peso_caja_camion_kg):null,precio_puesto_camion:truck?Number(form.precio_puesto_camion):null,flete_proveedor_id:Number(form.flete)>0?form.flete_proveedor_id:null,...prices,rebaja_planilla_flete:field||nampiEnPie?0:form.rebaja_planilla_flete===''?0:Number(form.rebaja_planilla_flete),tipo_cambio_resultado:form.tipo_cambio_resultado===''?null:Number(form.tipo_cambio_resultado),chofer:form.chofer.trim()||null,transportista:form.transportista.trim()||null,placa:form.placa.trim()||null,observaciones:form.observaciones.trim()||null}
    const {data:savedOrder,error:saveError}=await (order?supabase.from('ordenes_compra').update(payload).eq('id',order.id):supabase.from('ordenes_compra').insert({...payload,codigo:`OC-${Date.now()}`,creado_por:userId})).select('id').single()
    if(saveError){setSaving(false);setError(`No se pudo guardar la orden: ${saveError.message}`);return}
    if(form.boleta_entrada_id){const {data:linked,error:linkError}=await supabase.from('boletas_entrada').update({orden_compra_id:savedOrder.id}).eq('id',form.boleta_entrada_id).is('orden_compra_id',null).select('id').single();if(linkError||!linked){setSaving(false);setError('La orden se guardó, pero no se pudo enlazar la boleta. Revise si otro usuario la enlazó primero.');return}}
    setSaving(false);onSaved()
  }
  const remove=async()=>{
    if(!window.confirm(`¿Anular la compra ${order.codigo}? Quedará en Anuladas y saldrá de la lista activa. Si tiene boletas o pagos asociados, el programa impedirá la anulación.`))return
    setSaving(true);setError('')
    const {error:failure}=await supabase.rpc('anular_orden_compra',{p_orden_id:order.id})
    setSaving(false);if(failure){setError(`No se pudo anular: ${failure.message}`);return}onSaved()
  }
  return <div className="modalwrap"><div className="modal purchaseform"><div className="modalhead"><div><span>{order?'EDITAR REGISTRO':'NUEVO REGISTRO'}</span><h2>Orden de compra</h2></div><button onClick={close} aria-label="Cerrar"><X/></button></div>
    <div className="formsection"><h3>Fechas y boletas</h3><div className="formgrid"><label>Fecha de la orden de compra *<input type="date" value={form.fecha} onChange={e=>change('fecha',e.target.value)}/></label><label>Fecha prevista de llegada a planta<input type="date" value={form.fecha_labor} onChange={e=>change('fecha_labor',e.target.value)}/></label><label className="wide">Boleta de campo (referencia)<input value={form.boleta_campo_referencia} onChange={e=>change('boleta_campo_referencia',e.target.value)} placeholder="Número o referencia de la boleta"/></label>{linkedReceipts.length>0&&<p className="purchasehint wide">Boletas de planta enlazadas: {linkedReceipts.map(r=>r.codigo).join(', ')}</p>}<label className="wide">Enlazar otra boleta de entrada de planta<select value={form.boleta_entrada_id} onChange={e=>change('boleta_entrada_id',e.target.value)}><option value="">Enlazar después, cuando planta registre la entrada</option>{receipts.map(r=><option key={r.id} value={r.id}>{r.codigo} · {r.producto} · {new Date(r.fecha_hora).toLocaleDateString('es-CR')}</option>)}</select></label></div></div>
    <div className="formsection"><h3>Productor</h3><div className="formgrid"><label className="wide">Productor *<select value={form.proveedor_id} onChange={e=>chooseProvider(e.target.value)}><option value="">Seleccione un productor</option>{providers.map(p=><option key={p.id} value={p.id}>{p.nombre}</option>)}</select></label>{!form.proveedor_id&&order?.productor_nombre&&<p className="purchasehint wide">Productor registrado anteriormente: {order.productor_nombre}. Puede seleccionar su ficha para vincularlo.</p>}<button className="purchase-new-producer" type="button" onClick={()=>setNewProducer({nombre:'',cedula:'',residencia:'',telefono:'',zona:'',tipo:'Agricultor',productos:''})}>+ Nuevo productor</button></div>{newProducer&&<div className="producer-card"><strong>Ficha del productor nuevo</strong><div className="formgrid"><label>Nombre completo *<input value={newProducer.nombre} onChange={e=>setNewProducer({...newProducer,nombre:e.target.value})}/></label><label>Cédula<input value={newProducer.cedula} onChange={e=>setNewProducer({...newProducer,cedula:e.target.value})}/></label><label>Dirección o residencia<input value={newProducer.residencia} onChange={e=>setNewProducer({...newProducer,residencia:e.target.value})}/></label><label>Teléfono<input type="tel" value={newProducer.telefono} onChange={e=>setNewProducer({...newProducer,telefono:e.target.value})}/></label><label>Zona<input value={newProducer.zona} onChange={e=>setNewProducer({...newProducer,zona:e.target.value})}/></label><label>Tipo<select value={newProducer.tipo} onChange={e=>setNewProducer({...newProducer,tipo:e.target.value})}><option>Agricultor</option><option>Intermediario</option><option>Propio</option></select></label><label className="wide">Productos que entrega (separados por coma)<input value={newProducer.productos} onChange={e=>setNewProducer({...newProducer,productos:e.target.value})}/></label></div><div className="producer-actions"><button type="button" onClick={()=>setNewProducer(null)}>Cancelar</button><button type="button" className="primary" disabled={saving} onClick={createProducer}>Guardar productor</button></div></div>}</div>
    <div className="formsection"><h3>Modalidad de compra</h3><div className="formgrid"><label className="wide">Modalidad de compra<select value={form.tipo_compra} onChange={e=>setForm(current=>({...current,tipo_compra:e.target.value,...(e.target.value==='Producto listo/parafinado'?{producto:'Yuca',unidad:'Quintales (46 kg)'}:['Puesto en camión','En campo'].includes(e.target.value)?{unidad:'Cajas',cantidad_comprada:current.unidad==='Cajas'?current.cantidad_comprada:'',cantidad_recibida:''}:{})}))}>{['A rendimiento','Producto listo/parafinado','Puesto en camión','En campo','En pie','Cosecha propia','Otra'].map(x=><option key={x}>{x}</option>)}</select></label></div></div>
    <div className="formsection"><h3>{truck?'Cantidad y precio pactado de la yuca':'Producto y cantidades'}</h3><div className="formgrid"><label>Producto *<select value={form.producto} onChange={e=>change('producto',e.target.value)}><option value="">Seleccione un producto</option>{products.map(p=><option key={p} value={p}>{p}</option>)}</select></label>{!yucaRendimiento&&<label>Unidad<select disabled={ready||truck||field} value={truck||field?'Cajas':form.unidad} onChange={e=>change('unidad',e.target.value)}>{['Kilogramos','Quintales (46 kg)','Cajas','Sacos','Unidades'].map(u=><option key={u}>{u}</option>)}</select></label>}{!yucaRendimiento&&<label>{truck?'Cantidad pagada: cajas compradas *':field?'Cajas de primera compradas *':ready?'Cantidad comprada (quintales de 46 kg)':'Cantidad de producto comprado'}<input type="number" min="0" step="0.01" inputMode="decimal" value={form.cantidad_comprada} onChange={e=>change('cantidad_comprada',e.target.value)}/></label>}{!yucaRendimiento&&!truck&&!field&&<label>Cantidad de producto que llegó<input type="number" min="0" step="0.01" inputMode="decimal" value={form.cantidad_recibida} onChange={e=>change('cantidad_recibida',e.target.value)}/></label>}{truck&&<><label>Kilos pagados por cada caja (kg) *<input type="number" min="0.001" step="0.001" inputMode="decimal" value={form.peso_caja_camion_kg} onChange={e=>change('peso_caja_camion_kg',e.target.value)}/></label><label>Precio acordado por la yuca (₡/quintal de 46 kg) *<input type="number" min="0.01" step="0.01" inputMode="decimal" value={form.precio_puesto_camion} onChange={e=>change('precio_puesto_camion',e.target.value)}/></label><div className="receipt-calculation wide">{truckQuintals.toLocaleString('es-CR',{maximumFractionDigits:3})} quintales × ₡ {Number(form.precio_puesto_camion||0).toLocaleString('es-CR')} = <b>₡ {truckAmount.toLocaleString('es-CR',{maximumFractionDigits:2})}</b> para el agricultor. El rendimiento de planta no cambia este pago.</div></>}</div></div>
    {field&&<div className="formsection"><h3>Pesaje y pago pactado en campo</h3><p className="purchasehint">Ingrese hasta 20 pesos en las casillas: el promedio se calcula con los pesos anotados. También puede escribir directamente el promedio acordado. El rendimiento posterior de planta no modifica este pago.</p><div className="formgrid">{weightFields(boxSample,setBoxSample,'campo_promedio_caja_kg','cajas de primera')}<label>Promedio bruto por caja (kg) *<input type="number" min="0.001" step="0.001" value={form.campo_promedio_caja_kg} onChange={e=>change('campo_promedio_caja_kg',e.target.value)}/></label><label>Peso de la caja plástica (kg por caja)<input type="number" min="0" step="0.001" value={form.campo_tara_caja_kg} onChange={e=>change('campo_tara_caja_kg',e.target.value)}/></label><label>Tierra acordada (kg por caja)<input type="number" min="0" step="0.001" value={form.campo_tierra_caja_kg} onChange={e=>change('campo_tierra_caja_kg',e.target.value)}/></label><label>Precio primera en campo (₡/quintal de 46 kg) *<input type="number" min="0.01" step="0.01" value={form.precio_campo} onChange={e=>change('precio_campo',e.target.value)}/></label><div className="receipt-calculation wide">Peso neto pagable por caja: {Math.max(0,Number(form.campo_promedio_caja_kg||0)-Number(form.campo_tara_caja_kg||0)-Number(form.campo_tierra_caja_kg||0)).toLocaleString('es-CR',{maximumFractionDigits:3})} kg · {Number(form.cantidad_comprada||0)} cajas · Primera neta: {fieldFirstKg.toLocaleString('es-CR',{maximumFractionDigits:2})} kg · {(fieldFirstKg/46).toLocaleString('es-CR',{maximumFractionDigits:3})} quintales · <b>₡ {fieldFirstPay.toLocaleString('es-CR',{maximumFractionDigits:2})}</b></div><label>Sacos de rechazo pagados<input type="number" min="0" step="1" value={form.campo_sacos} onChange={e=>change('campo_sacos',e.target.value)}/></label><label>Promedio bruto por saco (kg)<input type="number" min="0" step="0.001" value={form.campo_promedio_saco_kg} onChange={e=>change('campo_promedio_saco_kg',e.target.value)}/></label>{weightFields(sackSample,setSackSample,'campo_promedio_saco_kg','sacos de rechazo')}<label>Descuento acordado al rechazo (%)<input type="number" min="0" max="99.99" step="0.01" value={form.campo_descuento_rechazo_pct} onChange={e=>change('campo_descuento_rechazo_pct',e.target.value)}/></label><label>Precio rechazo en campo (₡/quintal)<input type="number" min="0" step="0.01" value={form.campo_precio_rechazo} onChange={e=>change('campo_precio_rechazo',e.target.value)}/></label><div className="receipt-calculation wide">Peso neto pagable por saco: {(Number(form.campo_promedio_saco_kg||0)*(1-Number(form.campo_descuento_rechazo_pct||0)/100)).toLocaleString('es-CR',{maximumFractionDigits:3})} kg · {Number(form.campo_sacos||0)} sacos · Rechazo neto: {fieldRejectKg.toLocaleString('es-CR',{maximumFractionDigits:2})} kg · {(fieldRejectKg/46).toLocaleString('es-CR',{maximumFractionDigits:3})} quintales · <b>₡ {fieldRejectPay.toLocaleString('es-CR',{maximumFractionDigits:2})}</b></div><label>Planilla de arranca (₡)<input type="number" min="0" step="0.01" value={form.cuadrilla_arranca} onChange={e=>change('cuadrilla_arranca',e.target.value)}/></label><label className="wide">¿A quién se le paga la planilla y los otros costos de campo? *<select value={form.planilla_proveedor_id} onChange={e=>change('planilla_proveedor_id',e.target.value)}><option value="">Seleccione la cuadrilla o beneficiario</option>{providers.map(p=><option key={p.id} value={p.id}>{p.nombre}</option>)}</select></label><label className="wide">Nueva cuadrilla o beneficiario de la planilla<input value={newCrew} onChange={e=>setNewCrew(e.target.value)} placeholder="Nombre de quien cobra la arranca"/></label><button type="button" onClick={createCrew} disabled={saving||!newCrew.trim()}>+ Guardar beneficiario de planilla</button><label>Encargados (₡)<input type="number" min="0" step="0.01" value={form.campo_encargados} onChange={e=>change('campo_encargados',e.target.value)}/></label><label>Otros costos de campo (₡)<input type="number" min="0" step="0.01" value={form.campo_otros_costos} onChange={e=>change('campo_otros_costos',e.target.value)}/></label><label>Detalle de otros costos<input value={form.campo_otros_detalle} onChange={e=>change('campo_otros_detalle',e.target.value)}/></label><div className="receipt-calculation wide">Pago al productor (primera + rechazo): <b>₡ {(fieldFirstPay+fieldRejectPay).toLocaleString('es-CR',{maximumFractionDigits:2})}</b> · Planilla y otros costos: ₡ {fieldCrewCost.toLocaleString('es-CR',{maximumFractionDigits:2})} · Flete: ₡ {Number(form.flete||0).toLocaleString('es-CR',{maximumFractionDigits:2})} · <b>Costo real de la yuca: ₡ {fieldTotalCost.toLocaleString('es-CR',{maximumFractionDigits:2})}</b></div></div></div>}
    {ownProducer&&<div className="formsection"><h3>Finca y lote de producción propia</h3><p className="purchasehint">Esta compra de Agro Solano quedará asignada al lote para registrar lo que la exportadora le reconoce y paga a esa finca.</p><div className="formgrid"><label>Finca *<select value={selectedFarmId} onChange={e=>{setFarmId(e.target.value);change('finca_lote_id','')}}><option value="">Seleccione una finca</option>{farms.map(f=><option key={f.id} value={f.id}>{f.nombre}</option>)}</select></label><label>Lote y año *<select value={form.finca_lote_id} onChange={e=>change('finca_lote_id',e.target.value)}><option value="">Seleccione un lote</option>{lots.filter(l=>l.finca_id===selectedFarmId).map(l=><option key={l.id} value={l.id}>{l.anio} · {l.nombre}{l.producto?` · ${l.producto}`:''}</option>)}</select></label><label>Nueva finca<input value={newFarm} onChange={e=>setNewFarm(e.target.value)} placeholder="Si no aparece en la lista"/></label><button type="button" onClick={createFarm} disabled={saving||!newFarm.trim()}>+ Crear finca</button><label>Año del nuevo lote<input type="number" min="2000" max="2100" value={lotYear} onChange={e=>setLotYear(e.target.value)}/></label><label>Nuevo lote<input value={newLot} onChange={e=>setNewLot(e.target.value)} placeholder="Ejemplo: Lote 1"/></label><button type="button" onClick={createLot} disabled={saving||!selectedFarmId||!newLot.trim()}>+ Crear lote</button></div></div>}
    <div className="formsection"><h3>{truck?'Precios por calidad para comparar el rendimiento':'Acuerdo de compra y precios'}</h3><div className="formgrid"><p className="purchasehint wide">{truck?'Precios de mercado para comparar con el rendimiento. El pago fijo al agricultor se calculó arriba y no cambia con estos precios.':ready?'Yuca ya lista: registre solamente el precio Europa por quintal de 46 kg.':nampiEnPie?`${form.producto} en pie: registre el precio total del lote. Las entregas y rendimientos permanecen abiertos para seguir agregando cada día; el pago del lote aparece una sola vez.`:nampi?`${form.producto} a rendimiento puesto en planta: indique un precio por quintal de 46 kg. El pago se calcula con las partidas que planta marque como pagadas al productor.`:field?'Estos precios sirven para comparar el rendimiento obtenido en planta; el pago en campo se calcula con el pesaje anterior.':'Precios acordados en colones por quintal de 46 kg. El pago final por rendimiento queda pendiente de la boleta de planta.'}</p>{[['precio_europa',ready?'Yuca Europa lista/parafinada (₡/quintal)':'Yuca europea (₡/quintal)'],['precio_eeuu','Yuca estadounidense o genérica (₡/quintal)'],['precio_segunda_gruesa','Segunda gruesa (₡/quintal)'],['precio_segunda_menuda','Segunda menuda, cuando se paga (₡/quintal)'],['precio_rechazo','Rechazo (₡/quintal)'],['precio_campo',nampi?`${form.producto} puesto en planta (₡/quintal de 46 kg)`:'Precio en campo (₡/quintal)'],['precio_en_pie','Precio en pie (₡ por lote)'],['flete','Flete acordado (₡)'],['cuadrilla_arranca','Cuadrilla de arranca (₡)'],['adelanto','Adelanto entregado (₡)']].filter(([key])=>ready?['precio_europa','adelanto'].includes(key):nampi?[nampiEnPie?'precio_en_pie':'precio_campo','cuadrilla_arranca','adelanto'].includes(key):truck?['precio_europa','precio_eeuu','precio_segunda_gruesa','precio_segunda_menuda','precio_rechazo','cuadrilla_arranca','adelanto'].includes(key):field?['precio_europa','precio_eeuu','precio_segunda_gruesa','precio_segunda_menuda','precio_rechazo','adelanto'].includes(key):yucaRendimiento?['precio_europa','precio_eeuu','precio_segunda_gruesa','adelanto'].includes(key):!['flete'].includes(key)).map(([key,label])=><label key={key}>{label}<input type="number" min="0" step="0.01" inputMode="decimal" value={form[key]} onChange={e=>change(key,e.target.value)} placeholder="Opcional"/></label>)}<p className="purchasehint wide">El adelanto pagado que anote aquí se descuenta de la cuenta por pagar de esta compra. Puede registrar el movimiento bancario después, cuando lleve ese control.</p>{nampiEnPie&&<><label>Precio ñampí si fuera a rendimiento (₡/quintal)<input type="number" min="0" step="0.01" value={form.precio_nampi_rendimiento} onChange={e=>change('precio_nampi_rendimiento',e.target.value)} placeholder="Para comparar"/></label><label>Precio cabeza si fuera a rendimiento (₡/quintal)<input type="number" min="0" step="0.01" value={form.precio_cabeza_rendimiento} onChange={e=>change('precio_cabeza_rendimiento',e.target.value)} placeholder="Para comparar"/></label>{Number(form.cuadrilla_arranca)>0&&<><label className="wide">¿A quién se le paga la cuadrilla de arranca? *<select value={form.planilla_proveedor_id} onChange={e=>change('planilla_proveedor_id',e.target.value)}><option value="">Seleccione la cuadrilla</option>{providers.map(p=><option key={p.id} value={p.id}>{p.nombre}</option>)}</select></label><label className="wide">Nueva cuadrilla<input value={newCrew} onChange={e=>setNewCrew(e.target.value)}/></label><button type="button" onClick={createCrew} disabled={saving||!newCrew.trim()}>+ Guardar cuadrilla</button></>}</>}{!field&&!nampiEnPie&&!yucaRendimiento&&<><label className="wide">Rebajar planilla y flete del saldo a pagar (₡)<input type="number" min="0" step="0.01" inputMode="decimal" value={form.rebaja_planilla_flete} onChange={e=>change('rebaja_planilla_flete',e.target.value)} placeholder="0"/></label><p className="purchasehint wide">Esta rebaja se aplica una sola vez al total de la compra, incluso si tiene varias boletas. El flete con beneficiario se registra además como cuenta por pagar separada. Esta rebaja reduce el saldo del agricultor una sola vez; no descuenta el flete de su beneficiario.</p></>}{ready&&form.cantidad_comprada!==''&&Number(form.precio_europa)>0&&<p className="purchasehint wide">Costo previsto: ₡ {(Number(form.cantidad_comprada)*Number(form.precio_europa)).toLocaleString('es-CR',{maximumFractionDigits:2})} · {form.cantidad_comprada} quintales de yuca Europa lista.</p>}</div></div>
    {order&&!field&&<div className="formsection"><h3>Rendimiento de planta para esta compra</h3>{nampiEnPie&&<p className="purchasehint">Compra en pie: ₡ {Number(form.precio_en_pie||0).toLocaleString('es-CR')} por el lote. Se han registrado {(yieldDetails.reduce((sum,r)=>sum+Number(r.kg_resultado||0),0)/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales en las boletas enlazadas. Puede finalizar cada boleta terminada y seguir registrando nuevas entregas hasta cerrar la compra.</p>}{yieldDetails.length?<><div className="purchase-yield-list">{yieldDetails.map((r,i)=><div key={i}><span>{r.boleta} · {r.calidad} · {(Number(r.kg_resultado)/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales</span><b>{nampiEnPie?'Rendimiento del lote':!truck&&!r.paga_productor?'No se paga':yieldAmount(r)===null?'Falta precio':`₡ ${yieldAmount(r).toLocaleString('es-CR',{maximumFractionDigits:0})}`}</b></div>)}</div>{!nampiEnPie&&<div className="receipt-calculation">{truck?'Valor de referencia del rendimiento':'Subtotal estimado según rendimiento'}: <b>₡ {yieldTotal.toLocaleString('es-CR',{maximumFractionDigits:0})}</b>{pendingPrice?' · Falta acordar precios para completar el cálculo.':''}</div>}{truck?<p className="purchasehint">Pago fijo al agricultor: ₡ {Math.max(0,truckAmount-Number(form.rebaja_planilla_flete||0)).toLocaleString('es-CR')} · Flete por separado: ₡ {Number(form.flete||0).toLocaleString('es-CR')}. La diferencia entre el valor de referencia del rendimiento y el costo pactado es ₡ {(yieldTotal-truckAmount-Number(form.flete||0)).toLocaleString('es-CR',{maximumFractionDigits:2})}; es una referencia, no una liquidación al agricultor.</p>:<p className="purchasehint">Rebaja por planilla y flete: ₡ {Number(form.rebaja_planilla_flete||0).toLocaleString('es-CR')} · Saldo estimado: ₡ {Math.max(0,(nampiEnPie?Number(form.precio_en_pie||0):yieldTotal)-Number(form.rebaja_planilla_flete||0)).toLocaleString('es-CR')}. El adelanto se registra aparte.</p>}</>:<p className="purchasehint">Todavía no hay rendimientos registrados en las boletas enlazadas.</p>}</div>}
    {order&&nampiEnPie&&!order.en_pie_finalizada_en&&<div className="formsection"><h3>Ñampí y cabeza para la empacadora</h3><p className="purchasehint">Abra una boleta de esta compra y use «Agregar ñampí a planta» o «Agregar cabeza de ñampí a planta». Puede registrar los dos productos en la misma boleta, cada uno con sus propias cajas y kilos. Esto es distinto de vender por fuera.</p><div className="pie-purchase-receipts">{linkedReceipts.map(b=><button type="button" key={b.id} disabled={openingReceipt} onClick={()=>openPlantReceipt(b.id)}>Abrir {b.codigo} · {new Date(b.fecha_hora).toLocaleDateString('es-CR')} · agregar producto a planta</button>)}<button type="button" disabled={openingReceipt} onClick={()=>openPlantReceipt(null)}>+ Nueva boleta de planta de esta compra</button></div></div>}{order&&nampiEnPie&&!order.en_pie_finalizada_en&&<div className="formsection"><h3>Vender ñampí o cabeza directamente en campo</h3><p className="purchasehint">Venta sin pedido de venta. Quedará vinculada a esta compra y a una de sus boletas, y se sumará al resultado del lote. No registre la misma cantidad otra vez como producto empacado.</p>{linkedReceipts.length?<div className="formgrid"><label>Boleta de esta compra *<select value={pieSale.boleta_id} onChange={e=>setPieSale(current=>({...current,boleta_id:e.target.value}))}><option value="">Seleccione boleta</option>{linkedReceipts.map(b=><option key={b.id} value={b.id}>{b.codigo} · {new Date(b.fecha_hora).toLocaleDateString('es-CR')}</option>)}</select></label><label>Fecha de venta<input type="date" value={pieSale.fecha} onChange={e=>setPieSale(current=>({...current,fecha:e.target.value}))}/></label><label>Producto<select value={pieSale.producto} onChange={e=>setPieSale(current=>({...current,producto:e.target.value}))}><option>Ñampí</option><option>Cabeza de ñampí</option></select></label><label>Comprador *<input value={pieSale.comprador} onChange={e=>setPieSale(current=>({...current,comprador:e.target.value}))}/></label><label>Cantidad *<input type="number" min="0.001" step="0.001" value={pieSale.cantidad} onChange={e=>setPieSale(current=>({...current,cantidad:e.target.value}))}/></label><label>Unidad<select value={pieSale.unidad} onChange={e=>setPieSale(current=>({...current,unidad:e.target.value,peso_saco_kg:e.target.value==='Sacos'?current.peso_saco_kg:''}))}><option>Sacos</option><option>Quintales (46 kg)</option></select></label>{pieSale.unidad==='Sacos'&&<label>Peso promedio por saco (kg) *<input type="number" min="0.001" step="0.001" value={pieSale.peso_saco_kg} onChange={e=>setPieSale(current=>({...current,peso_saco_kg:e.target.value}))}/></label>}<label>Precio por {pieSale.unidad==='Sacos'?'saco':'quintal'} *<input type="number" min="0" step="0.01" value={pieSale.precio_unitario} onChange={e=>setPieSale(current=>({...current,precio_unitario:e.target.value}))}/></label><label>Moneda<select value={pieSale.moneda} onChange={e=>setPieSale(current=>({...current,moneda:e.target.value}))}><option>CRC</option><option>USD</option></select></label><button className="purchase-new-producer" type="button" disabled={addingPieSale} onClick={savePieSale}>{addingPieSale?'Guardando…':'+ Guardar venta directa'}</button></div>:<p className="purchasehint">Primero registre una boleta de entrada para vincularle esta venta.</p>}</div>}
    {order&&nampiEnPie&&<div className="formsection"><h3>Resultado de la compra en pie</h3><p className="purchasehint">{order.en_pie_finalizada_en?'Compra finalizada.':'Compra abierta: puede agregar más boletas y ventas directas.'} El precio del lote se paga una sola vez, aunque produzca ñampí y cabeza.</p><div className="receipt-calculation">Planta: ñampí {(pieYieldKg('Ñampí')/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales · cabeza {(pieYieldKg('Cabeza de ñampí')/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales.</div><div className="receipt-calculation">Venta directa sin pedido: {directSales.length} partida(s) · ñampí {(outsideKg('Ñampí')/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales · cabeza {(outsideKg('Cabeza de ñampí')/46).toLocaleString('es-CR',{maximumFractionDigits:2})} quintales · ₡ {outsideSales.CRC.toLocaleString('es-CR',{maximumFractionDigits:2})} · USD {outsideSales.USD.toLocaleString('es-CR',{maximumFractionDigits:2})}.</div>{directSales.length>0&&<details className="purchasehint"><summary>Ver ventas directas</summary>{directSales.map(v=><p key={v.id}>{v.fecha} · {v.comprador} · {v.producto} · {v.cantidad} {v.unidad} × {v.moneda} {Number(v.precio_unitario).toLocaleString('es-CR')}</p>)}</details>}<div className="receipt-calculation">Costo real: lote ₡ {Number(form.precio_en_pie||0).toLocaleString('es-CR')} + cuadrilla ₡ {Number(form.cuadrilla_arranca||0).toLocaleString('es-CR')} + flete ₡ {Number(form.flete||0).toLocaleString('es-CR')} = <b>₡ {pieRealCost.toLocaleString('es-CR',{maximumFractionDigits:2})}</b></div><div className="receipt-calculation">Si se pagara a rendimiento: {pieMissingPrice?'Faltan precios de uno de los productos':<b>₡ {pieHypothetical.toLocaleString('es-CR',{maximumFractionDigits:2})}</b>} · Diferencia frente al costo real: {pieMissingPrice?'Pendiente':`₡ ${(pieHypothetical-pieRealCost).toLocaleString('es-CR',{maximumFractionDigits:2})}`}</div><div className="receipt-calculation">Ventas de pedidos finalizados: ₡ {sold.CRC.toLocaleString('es-CR',{maximumFractionDigits:2})} · USD {sold.USD.toLocaleString('es-CR',{maximumFractionDigits:2})} · Ventas directas: ₡ {outsideSales.CRC.toLocaleString('es-CR',{maximumFractionDigits:2})} · USD {outsideSales.USD.toLocaleString('es-CR',{maximumFractionDigits:2})}</div>{sold.USD+outsideSales.USD>0&&<div className="formgrid"><label>Tipo de cambio para el resultado (₡ por USD)<input type="number" min="0.01" step="0.01" value={form.tipo_cambio_resultado} onChange={e=>change('tipo_cambio_resultado',e.target.value)}/></label></div>}{(sold.USD+outsideSales.USD===0||Number(form.tipo_cambio_resultado)>0)&&<div className="receipt-calculation">Resultado registrado (ventas menos costo real): <b>₡ {(pieRevenue-pieRealCost).toLocaleString('es-CR',{maximumFractionDigits:2})}</b></div>}<p className="purchasehint">El resultado puede ser parcial hasta vender todo lo producido; la comparación a rendimiento usa los kilos registrados de ambos productos.</p></div>}
    <div className="formsection"><h3>Transporte</h3><div className="formgrid"><label>Chofer<input value={form.chofer} onChange={e=>change('chofer',e.target.value)}/></label>{!truck&&<label>Transportista<input value={form.transportista} onChange={e=>change('transportista',e.target.value)}/></label>}<label>Placa<input value={form.placa} onChange={e=>change('placa',e.target.value)}/></label><label>Precio del flete acordado (₡)<input type="number" min="0" step="0.01" inputMode="decimal" value={form.flete} onChange={e=>change('flete',e.target.value)} placeholder="Sin flete"/></label>{Number(form.flete)>0&&<><label className="wide">¿A quién se le paga el flete? *<select value={form.flete_proveedor_id} onChange={e=>{const chosen=providers.find(p=>p.id===e.target.value);setForm(current=>({...current,flete_proveedor_id:e.target.value,transportista:chosen?.nombre||current.transportista}))}}><option value="">Seleccione agricultor o transportista</option>{providers.map(p=><option key={p.id} value={p.id}>{p.nombre}{p.id===form.proveedor_id?' · agricultor de esta compra':''}</option>)}</select></label><label className="wide">Nuevo transportista o beneficiario del flete<input value={newCarrier} onChange={e=>setNewCarrier(e.target.value)} placeholder="Nombre de quien cobra el flete"/></label><button type="button" onClick={createCarrier} disabled={saving||!newCarrier.trim()}>+ Guardar beneficiario del flete</button><p className="purchasehint wide">El flete genera una cuenta por pagar distinta, incluso cuando lo hace el agricultor. Registre su pago en Bancos por separado.</p></>}<label className="wide">Observaciones<textarea rows="3" value={form.observaciones} onChange={e=>change('observaciones',e.target.value)}/></label></div></div>
    {error&&<div className="formerror">{error}</div>}<div className="modalactions">{order&&order.estado!=='Anulada'&&<button className="danger-action" type="button" onClick={remove} disabled={saving}>Eliminar / anular compra</button>}<button onClick={close} disabled={saving}>Cancelar</button><button className="primary" onClick={save} disabled={saving||!!newProducer}>{saving?'Guardando…':order?'Guardar cambios':'Guardar orden'}</button></div>
  </div></div>
}
